mapper.select:
SELECT o.id, o.opp_no, o.opp_name, o.customer_id, c.customer_name, o.contact_id, cc.contact_name, o.stage_id, o.stage_name, o.probability, o.expected_amount, o.actual_amount, o.expected_date, o.close_date, o.source, o.status, o.owner_id, u.user_name AS owner_name, o.winner_quote_id, q.quote_no AS winner_quote_no, q.quote_name AS winner_quote_name, o.description, o.remark, o.create_time, o.update_time FROM crm_opportunity o LEFT JOIN crm_customer c ON o.customer_id = c.id LEFT JOIN crm_customer_contact cc ON o.contact_id = cc.id LEFT JOIN sys_user u ON o.owner_id = u.id LEFT JOIN crm_quote q ON o.winner_quote_id = q.id WHERE 1=1
AND o.opp_name LIKE CONCAT('%', #{query.oppName}, '%')
AND o.customer_id = #{query.customerId}
AND o.stage_id = #{query.stageId}
AND o.status = #{query.status}
AND o.owner_id = #{query.ownerId}
AND o.source = #{query.source}
ORDER BY o.create_time DESC
